package cl.bcs.oracle;

import java.lang.reflect.Type;
import java.sql.Connection;
import java.util.HashSet;
import java.util.Set;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;

/**
 * Runtime of the REGISTERED DOUBLES (classes generated by tools/gen_doubles.py for the collaborators that are NOT in the closure:
 * Tesoreria CrearIngresoEgreso, Mesa Spot, Plataforma CalcularParidad / EntregarPreciosTasas / SaldoFlujoCaja / AgregarLog / ...).
 * Each call is RECORDED (collaborator, method, arguments as JSON) and answered from the case configuration:
 * <pre>
 * "colaboradores": { "CalcularParidad": { "defecto": {..JSON of the Salida..},
 *      "respuestas": [ { "cuando": {"0.p_Moneda": "USD"}, "respuesta": {..}, "una_vez": false } , { "error": "text" } ] } }
 * </pre>
 * "cuando" paths are dotted and start at the index of the argument (Connection excluded): "0.Campo.1.Otro". The first matching entry wins;
 * "error" makes the collaborator throw; with no matching entry and no "defecto" the call fails loudly (a case must script what it reaches).
 */
public final class Doubles {
    private static JsonObject config = new JsonObject();
    private static JsonArray calls = new JsonArray();
    private static JsonArray secuencias = new JsonArray();
    private static final Set<JsonObject> used = new HashSet<>();
    private static final Gson OUT = new GsonBuilder().serializeSpecialFloatingPointValues().setDateFormat("yyyy-MM-dd HH:mm:ss.SSS").serializeNulls().disableHtmlEscaping().create();
    private static final Gson IN = cl.bcs.utils.Utils.getGsonBuilder();

    private Doubles() { }

    public static void reset(JsonObject cfg) {
        config = cfg == null ? new JsonObject() : cfg;
        calls = new JsonArray();
        secuencias = new JsonArray();
        used.clear();
    }

    public static JsonArray calls() { return calls; }

    public static JsonArray secuencias() { return secuencias; }

    public static void registrarSecuencia(String nombre, long cantidad) {
        JsonObject o = new JsonObject();
        o.addProperty("secuencia", nombre);
        o.addProperty("cantidad", cantidad);
        secuencias.add(o);
    }

    @SuppressWarnings("unchecked")
    private static <E extends Throwable> void sneaky(Throwable t) throws E { throw (E) t; }

    public static <T> T answer(String colab, String metodo, Object[] args, Class<T> ret) {
        JsonArray argJson = new JsonArray();
        for (Object a : args) {
            if (a instanceof Connection) continue;
            argJson.add(OUT.toJsonTree(a));
        }
        JsonObject rec = new JsonObject();
        rec.addProperty("colaborador", colab);
        rec.addProperty("metodo", metodo);
        rec.add("argumentos", argJson);
        calls.add(rec);
        JsonObject c = config.has(colab) && config.get(colab).isJsonObject() ? config.getAsJsonObject(colab) : null;
        JsonObject hit = null;
        if (c != null && c.has("respuestas")) {
            for (JsonElement e : c.getAsJsonArray("respuestas")) {
                JsonObject r = e.getAsJsonObject();
                if (r.has("una_vez") && r.get("una_vez").getAsBoolean() && used.contains(r)) continue;
                if (matches(r.has("cuando") ? r.getAsJsonObject("cuando") : null, argJson)) { hit = r; break; }
            }
        }
        if (hit != null) {
            used.add(hit);
            if (hit.has("error")) {
                Throwable t = new Exception(hit.get("error").getAsString());
                rec.addProperty("respuesta", "error: " + hit.get("error").getAsString());
                Doubles.<RuntimeException>sneaky(t);
            }
            JsonElement resp = hit.get("respuesta");
            rec.add("respuesta", resp);
            return convert(resp, ret);
        }
        if (c != null && c.has("defecto")) {
            rec.add("respuesta", c.get("defecto"));
            return convert(c.get("defecto"), ret);
        }
        rec.addProperty("respuesta", "SIN RESPUESTA CONFIGURADA");
        throw new IllegalStateException("oracle double " + colab + "." + metodo + ": no canned answer configured for this call");
    }

    private static <T> T convert(JsonElement e, Class<T> ret) {
        if (ret == Void.class || e == null || e.isJsonNull()) return null;
        return IN.fromJson(e, (Type) ret);
    }

    private static boolean matches(JsonObject cuando, JsonArray args) {
        if (cuando == null) return true;
        for (String path : cuando.keySet()) {
            JsonElement cur = args;
            for (String p : path.split("\\.")) {
                if (cur == null || cur.isJsonNull()) { cur = null; break; }
                if (cur.isJsonArray()) {
                    int i = Integer.parseInt(p);
                    cur = i < cur.getAsJsonArray().size() ? cur.getAsJsonArray().get(i) : null;
                } else if (cur.isJsonObject()) {
                    cur = cur.getAsJsonObject().get(p);
                } else { cur = null; }
            }
            JsonElement want = cuando.get(path);
            boolean wantNull = want == null || want.isJsonNull();
            boolean gotNull = cur == null || cur.isJsonNull();
            if (wantNull != gotNull) return false;
            if (!wantNull) {
                if (!(cur instanceof JsonPrimitive) || !(want instanceof JsonPrimitive)) return false;
                java.math.BigDecimal a = num(cur.getAsString()), b = num(want.getAsString());
                if (a != null && b != null ? a.compareTo(b) != 0 : !cur.getAsString().equals(want.getAsString())) return false;
            }
        }
        return true;
    }

    private static java.math.BigDecimal num(String s) {
        try { return new java.math.BigDecimal(s); } catch (NumberFormatException ex) { return null; }
    }
}
